<?php
$pageTitle="Laporan Penjualan"; require "header.php";
$rows=$conn->query("SELECT * FROM view_laporan_penjualan ORDER BY tanggal DESC,id_transaksi DESC");
$sum=$conn->query("SELECT COALESCE(SUM(total_belanja),0) total FROM tbl_transaksi")->fetch_assoc()["total"]??0;
$above=$conn->query("SELECT id_transaksi,tanggal,total_belanja FROM tbl_transaksi WHERE total_belanja>(SELECT AVG(total_belanja) FROM tbl_transaksi) ORDER BY total_belanja DESC");
?>
<div class="card mb-3"><div class="card-body d-flex justify-content-between align-items-center"><div><div class="text-muted small">Total nilai transaksi</div><div class="stat-value"><?=rupiah($sum)?></div></div><div class="stat-icon"><i class="bi bi-graph-up-arrow"></i></div></div></div>
<div class="card mb-4"><div class="card-header">View Laporan Penjualan (JOIN)</div><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Tanggal</th><th>Pelanggan</th><th>Produk</th><th>Kategori</th><th>Qty</th><th>Subtotal</th><th>Total Transaksi</th></tr></thead><tbody><?php if($rows && $rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td><?=e($r["id_transaksi"])?></td><td><?=e($r["tanggal"])?></td><td><?=e($r["nama_pelanggan"])?></td><td><?=e($r["nama_produk"])?></td><td><?=e($r["nama_kategori"])?></td><td><?=e($r["jumlah"])?></td><td><?=rupiah($r["subtotal"])?></td><td><?=rupiah($r["total_belanja"])?></td></tr><?php endwhile;else:?><tr><td colspan="8" class="text-center p-4 text-muted">View belum memiliki data transaksi detail.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card"><div class="card-header">Analisis Subquery: Transaksi Di Atas Rata-rata</div><div class="table-responsive"><table class="table"><thead><tr><th>ID Transaksi</th><th>Tanggal</th><th>Total</th></tr></thead><tbody><?php if($above && $above->num_rows):while($r=$above->fetch_assoc()):?><tr><td>#<?=e($r["id_transaksi"])?></td><td><?=e($r["tanggal"])?></td><td><?=rupiah($r["total_belanja"])?></td></tr><?php endwhile;else:?><tr><td colspan="3" class="text-center p-4 text-muted">Tidak ada transaksi di atas rata-rata.</td></tr><?php endif;?></tbody></table></div></div>
<?php require "footer.php"; ?>
